/**
 * Operational intelligence — deterministic rules over the shared simulation state.
 *
 * Produces the insights, recommendations and "next actions" shown on the Overview,
 * the equipment inspector and the copilot. Every statement is computed from the same
 * metrics the dashboards show and carries its evidence; nothing is generated by an LLM.
 */
import { EQUIPMENT_BY_ID } from '../data/equipment';
import { BUFFERS, CONVEYOR_BY_ID, DEFECTS, DEFECT_ORDER, LINE, M2_PER_TILE, OPS_BY_ID, STAGES, STAGE_BY_ID, TARGET } from '../model/plant';
import type { StageId } from '../model/types';
import { batchAt, type SimState } from '../sim/engine';
import type { Tariffs } from '../sim/energy';
import { HEALTH_ASSETS, assess, formatH, type HealthAssessment } from '../sim/health';
import {
  bottleneck,
  HELD_UP_SHARE,
  TARGET_STATUS_LABEL,
  targetStatus,
  downtimePareto,
  fleetMetrics,
  lineMetrics,
  qualityIn,
  resolvePeriod,
  risingDefects,
  type Period,
} from '../sim/metrics';
import { formatClock, formatDuration } from '../sim/time';
import { lineGoodLostTiles } from './report';
import { constraintClaim, constraintPhrase, type ConstraintClaim } from './summary';

export type InsightSeverity = 'critical' | 'serious' | 'warning' | 'info' | 'positive';
export type InsightKind = 'target' | 'stoppage' | 'bottleneck' | 'buffer' | 'quality' | 'health' | 'energy' | 'logistics' | 'shift';

export type InsightLink =
  | { kind: 'equipment'; id: string; label: string }
  | { kind: 'vehicle'; id: string; label: string }
  /** An event's full report in Events & Reports. */
  | { kind: 'event'; id: string; label: string }
  /** A stage's detail view in Production. */
  | { kind: 'stage'; id: import('../model/types').MonitoredStageId; label: string }
  | { kind: 'workspace'; id: Exclude<import('../app/store').WorkspaceId, 'twin'>; label: string };

export type Insight = {
  id: string;
  kind: InsightKind;
  severity: InsightSeverity;
  title: string;
  /** One-sentence explanation. */
  summary: string;
  /** Facts the insight is based on (traceable to metrics). */
  evidence: string[];
  /** Quantified effect, if any. */
  impact?: string;
  /**
   * Set when `impact` is a money estimate: the assumptions it rests on. Cards show it as
   * "estimate · assumptions shown" with these lines (honesty rule for financial figures).
   */
  estimate?: string[];
  recommendation?: string;
  equipmentId?: string;
  links: InsightLink[];
  /** Ordering weight (higher first). */
  weight: number;
};

const RANK: Record<InsightSeverity, number> = { critical: 500, serious: 400, warning: 300, info: 100, positive: 50 };
const m2 = (tiles: number) => Math.round(tiles * M2_PER_TILE).toLocaleString('en-GB');
const pct = (f: number | null, d = 1) => (f == null ? '—' : `${(f * 100).toFixed(d)} %`);
const name = (id: string) => EQUIPMENT_BY_ID[id]?.name ?? id;
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);

/** First response for each downtime reason (illustrative standard work). */
export { REASON_ACTIONS, DEFECT_ACTIONS } from '../model/actions';
import { DEFECT_ACTIONS } from '../model/actions';

// ── Rules ─────────────────────────────────────────────────────────────────────

function targetRule(s: SimState, p: Period): Insight[] {
  const lm = lineMetrics(s, p);
  if (lm.attainment == null || lm.target < 1) return [];
  const gap = lm.target - lm.output;
  const pareto = downtimePareto(s, p).slice(0, 3);
  const claim = constraintClaim(s);
  const status = targetStatus(lm.attainment);
  if (status === 'ahead' || status === 'on-track') {
    return [
      {
        id: 'target-ok',
        kind: 'target',
        severity: 'positive',
        title: `${TARGET_STATUS_LABEL[status]} · ${pct(lm.attainment, 0)}`,
        summary: `${m2(lm.output)} m² first-quality output against a ${m2(lm.target)} m² target for ${p.label.charAt(0).toLowerCase() + p.label.slice(1)}${gap > 0 ? ` — ${m2(gap)} m² short, within normal variation` : ''}.`,
        evidence: [`Line OEE ${lm.oee.oee.status === 'ok' ? pct(lm.oee.oee.value!) : '—'} (target ${pct(TARGET.oeeTarget, 0)}).`],
        links: [{ kind: 'workspace', id: 'production', label: 'Open Production' }],
        weight: RANK.positive,
      },
    ];
  }
  const ev = [
    `Output ${m2(lm.output)} m² vs target ${m2(lm.target)} m² (${pct(lm.attainment, 0)}).`,
    `Line OEE ${lm.oee.oee.status === 'ok' ? pct(lm.oee.oee.value!) : '—'}: availability ${lm.oee.availability.status === 'ok' ? pct(lm.oee.availability.value!) : '—'}, performance ${lm.oee.performance.status === 'ok' ? pct(lm.oee.performance.value!) : '—'}, quality ${lm.oee.quality.status === 'ok' ? pct(lm.oee.quality.value!) : '—'}.`,
  ];
  if (pareto.length) ev.push(`Largest unplanned losses: ${pareto.map((r) => `${r.label} ${Math.round(r.minutes)} min`).join(', ')}.`);
  ev.push(`${cap(constraintPhrase(claim))}.`);
  return [
    {
      id: 'target-gap',
      kind: 'target',
      severity: status === 'well-behind' ? 'serious' : 'warning',
      title: `${TARGET_STATUS_LABEL[status]} by ${m2(gap)} m²`,
      summary: `${p.label} output is ${pct(lm.attainment, 0)} of target; the gap is driven by ${pareto[0] ? `${pareto[0].label.toLowerCase()} and ` : ''}time lost at ${claim.constraining ? `${claim.name.toLowerCase()}, which is currently constraining output` : 'the kiln, the modeled design constraint'}.`,
      evidence: ev,
      impact: `${m2(gap)} m² behind plan`,
      recommendation: `${claim.constraining ? `Protect the constraint (${claim.name})` : 'Protect the kiln (the modeled design constraint)'}: keep its input buffer full and prioritise its repairs; then address ${pareto[0]?.label.toLowerCase() ?? 'the top downtime reason'}.`,
      links: [{ kind: 'workspace', id: 'production', label: 'Open Production' }],
      weight: RANK[status === 'well-behind' ? 'serious' : 'warning'] + gap / 50,
    },
  ];
}

function stoppageRule(s: SimState): Insight[] {
  const now = s.minute;
  const claim = constraintClaim(s);
  return s.events
    .filter((e) => e.end == null && (e.type === 'machine-fault' || e.type === 'machine-stop' || e.type === 'conveyor-stop'))
    .map((e) => {
      const id = e.asset.equipmentId!;
      const conv = CONVEYOR_BY_ID[id];
      const stage = (OPS_BY_ID[id]?.stage ?? conv?.to ?? null) as StageId | null;
      const minutes = now - e.start;
      const isConstraint = id === 'H-KILN' || (stage != null && (stage === LINE.designConstraint || (claim.constraining && stage === claim.processStage)));
      const sev: InsightSeverity = isConstraint || e.acc.constraintMin > 0 ? 'critical' : 'serious';
      // Buffer cover downstream of the stopped asset.
      const outBuf = conv ? conv.bufferId : stage ? STAGES[STAGES.findIndex((x) => x.id === stage) + 1]?.inputBuffer : null;
      const buf = outBuf ? BUFFERS.find((x) => x.id === outBuf) : null;
      const downstreamRate = STAGES.find((x) => x.inputBuffer === outBuf)?.machines.reduce((acc, m) => acc + (OPS_BY_ID[m].idealRatePerHour ?? 0), 0) ?? 0;
      const cover = buf && downstreamRate ? (s.buffers[buf.id] / downstreamRate) * 60 : null;
      // Same figure as the event report (kiln tiles held up × 24 h first-pass yield before the event).
      const lineLostM2 = m2(lineGoodLostTiles(s, e));
      const ownKiln = id === 'H-KILN';
      return {
        id: `stop-${e.id}`,
        kind: 'stoppage' as const,
        severity: sev,
        title: `${id} stopped · ${e.trigger.observed.find((o) => o.label.startsWith('Alarm'))?.value ?? ''}`.replace(/ · $/, '') + ` (${e.id})`,
        summary: `${name(id)} has been down for ${formatDuration(minutes)} (since ${formatClock(e.start)})${e.source === 'scenario' ? ' — scenario input' : ''}.`,
        evidence: [
          ...e.facts.slice(0, 2),
          e.acc.constraintMin > 0
            ? ownKiln
              ? `The kiln (line constraint) has been held up ${Math.round(e.acc.constraintMin)} min by this stop — ≈ ${lineLostM2} m² line output lost.`
              : `The kiln (line constraint) has been held up ${Math.round(e.acc.constraintMin)} min, attributed to this stop (inferred · likely) — ≈ ${lineLostM2} m² line output lost.`
            : 'Line output not affected yet — the buffers between this asset and the kiln are absorbing it.',
          ...(cover != null && buf ? [`Buffer ${buf.name} covers ≈ ${Math.round(cover)} min of downstream demand.`] : []),
        ],
        impact: e.acc.constraintMin > 0 ? `${lineLostM2} m² line output lost so far` : `${m2(e.acc.assetLostTiles)} m² not made at ${id} so far (recoverable while buffers cover it)`,
        recommendation: e.recommendations[0] ?? 'Dispatch maintenance to diagnose the stoppage.',
        equipmentId: id,
        links: [
          { kind: 'event' as const, id: e.id, label: `Report ${e.id}` },
          { kind: 'equipment' as const, id, label: `Locate ${id}` },
          { kind: 'workspace' as const, id: 'production' as const, label: 'Open Production' },
        ],
        weight: RANK[sev] + minutes + e.acc.constraintMin * 2,
      };
    });
}

/** Title and severity of the constraint insight, graded like the Overview (constraintClaim, src/intel/summary.ts). */
function constraintHeadline(c: ConstraintClaim): { title: string; severity: InsightSeverity } {
  if (c.kind === 'starving' || c.kind === 'blocking') return { title: `Bottleneck shifted to ${c.name}`, severity: 'warning' };
  if (c.constraining) return { title: `${c.name} is currently constraining output`, severity: 'warning' };
  if (c.kind === 'kiln-unknown') return { title: `Design constraint (modeled): ${c.name} · state unknown`, severity: 'info' };
  if (c.kind === 'planned') return { title: `Design constraint (modeled): ${c.name} · planned stop`, severity: 'info' };
  return { title: `Design constraint (modeled): ${c.name}`, severity: 'info' };
}

function bottleneckRule(s: SimState): Insight[] {
  const bn = bottleneck(s);
  const claim = constraintClaim(s);
  // The stage the claim names (the traced stage, or the kiln itself).
  const cur = bn.stages.find((r) => r.stage === claim.processStage) ?? bn.current;
  const machines = STAGE_BY_ID[cur.stage].machines;
  const at = bn.stages.indexOf(cur);
  const shifted = claim.kind === 'starving' || claim.kind === 'blocking';
  const up = shifted ? bn.stages.filter((r, i) => i < at && (r.blockedShare ?? 0) > HELD_UP_SHARE).map((r) => r.name) : [];
  const down = shifted ? bn.stages.filter((r, i) => i > at && (r.starvedShare ?? 0) > HELD_UP_SHARE).map((r) => r.name) : [];
  const ev = [`${cap(claim.detail)}.`];
  // Trace shares are evidence only while the kiln feed is current (a stale feed leaves the kiln's state unknown).
  if (claim.kind !== 'kiln-unknown') ev.push(`${cur.name} was active ${pct(cur.activeShare, 0)} of the last 2 h (starved ${pct(cur.starvedShare, 0)}, blocked ${pct(cur.blockedShare, 0)}, down ${pct(cur.downShare, 0)}).`);
  if (up.length) ev.push(`Blocked upstream: ${up.join(', ')}.`);
  if (down.length) ev.push(`Starved downstream: ${down.join(', ')}.`);
  if (cur.inputBufferLevel != null) ev.push(`Its input buffer is at ${pct(cur.inputBufferLevel, 0)}.`);
  const { title, severity } = constraintHeadline(claim);
  return [
    {
      id: 'bottleneck',
      kind: 'bottleneck',
      severity,
      title,
      summary: shifted
        ? `${cap(constraintPhrase(claim))}; every minute lost there is lost for the whole line (${STAGE_BY_ID[LINE.designConstraint].name.toLowerCase()} is the design constraint).`
        : `${cap(constraintPhrase(claim))}.`,
      evidence: ev,
      recommendation: shifted
        ? `Restore ${claim.name.toLowerCase()} capacity (${machines.join(', ')}): check rate settings and recent stops; until then reduce upstream overproduction.`
        : claim.kind === 'kiln-unknown'
          ? 'Restore the kiln data feed before acting on its state; until then the kiln is treated only as the modeled design constraint.'
          : claim.kind === 'kiln-slow'
            ? `Get the kiln back to its design rate: ${claim.evidence}.`
            : claim.kind === 'kiln-stopped'
              ? `Restore the kiln first — ${claim.evidence}; every minute it is stopped is line output lost.`
              : 'Keep the kiln fed: avoid starving it from upstream and schedule its maintenance in planned windows.',
      equipmentId: machines[0],
      links: machines.map((id) => ({ kind: 'equipment' as const, id, label: `Locate ${id}` })),
      weight: RANK[severity] + (cur.activeShare ?? 0) * 10,
    },
  ];
}

function bufferRule(s: SimState): Insight[] {
  const out: Insight[] = [];
  STAGES.forEach((st, i) => {
    if (!st.inputBuffer || i === 0) return;
    const buf = BUFFERS.find((b) => b.id === st.inputBuffer)!;
    if (buf.capacity < 500) return; // conveyor accumulations change too fast to be useful
    const inflow = STAGES[i - 1].machines.reduce((a, id) => a + s.machines[id].ratePerHour, 0);
    const outflow = st.machines.reduce((a, id) => a + s.machines[id].ratePerHour, 0);
    const level = s.buffers[buf.id];
    const net = inflow - outflow;
    if (net >= -50 || level <= 0) return;
    const minutesToEmpty = (level / -net) * 60;
    if (minutesToEmpty > 90) return;
    out.push({
      id: `buffer-${buf.id}`,
      kind: 'buffer',
      severity: minutesToEmpty < 30 ? 'serious' : 'warning',
      title: `${buf.name} empties in ≈ ${Math.round(minutesToEmpty)} min`,
      summary: `${STAGES[i - 1].name} is supplying ${Math.round(inflow)} tiles/h while ${st.name.toLowerCase()} draws ${Math.round(outflow)} tiles/h; ${st.name.toLowerCase()} will be starved when the buffer runs out.`,
      evidence: [`Buffer level ${pct(level / buf.capacity, 0)} of ${buf.capacity.toLocaleString('en-GB')} tiles.`],
      recommendation: `Restore ${STAGES[i - 1].name.toLowerCase()} output before the buffer empties, or plan a controlled slow-down of ${st.name.toLowerCase()}.`,
      equipmentId: buf.equipmentId ?? st.machines[0],
      links: [{ kind: 'equipment', id: buf.equipmentId ?? st.machines[0], label: `Locate ${buf.name}` }],
      weight: RANK[minutesToEmpty < 30 ? 'serious' : 'warning'] + (90 - minutesToEmpty),
    });
  });
  return out;
}

function qualityRule(s: SimState): Insight[] {
  const now = s.minute;
  const from = Math.floor((now - 60) / 60) * 60;
  const hrs = Math.max(1 / 60, (now - from) / 60);
  const recent = qualityIn(s, { from, to: now, label: '' });
  const ref = qualityIn(s, { from: Math.floor((now - 60 - 1440) / 60) * 60, to: Math.floor((now - 60) / 60) * 60, label: '' });
  if (recent.inspected < 300 || ref.inspected < 1000) return [];
  const rr = recent.rejected / recent.inspected;
  const rref = ref.rejected / ref.inspected;
  // The one rising-defect rule (risingDefects): the same category the Quality summary and the copilot name.
  const rise = risingDefects(s, { from: Math.max(0, now - 120), to: now, label: 'Last 2 h' });
  const top = rise.rising[0];
  if (rr < rref * 1.35 && !top) return [];
  // Without a rising category: the most frequent one of the last hour (for the standard check).
  const frequent = DEFECT_ORDER.map((d) => ({ d, n: recent.byDefect[d] })).sort((a, b) => b.n - a.n)[0].d;
  const d = top?.defect ?? frequent;
  const label = DEFECTS[d].label;
  const origin = DEFECTS[d].origin as StageId;
  const batch = batchAt(s, now - 180);
  const scenario = s.scenarios.some((sc) => sc.kind === 'quality-deterioration' && sc.start <= now && (sc.end == null || sc.end > now));
  const vsRef = rref > 0 ? `${(rr / rref).toFixed(1)}× the 24-hour reference (${pct(rref)})` : 'against no reject in the 24-hour reference';
  return [
    {
      id: 'quality',
      kind: 'quality',
      severity: rr > 0.05 ? 'serious' : 'warning',
      title: top ? `Reject rate ${pct(rr)} · ${label.toLowerCase()} rising` : `Reject rate ${pct(rr)} · ${label.toLowerCase()} most frequent`,
      summary: top
        ? `Rejects at sorting are ${vsRef}; ${label.toLowerCase()} is up ${top.ratio!.toFixed(1)}× over the last 2 h and usually originates at ${STAGE_BY_ID[origin].name.toLowerCase()}.${scenario ? ' (Scenario input active.)' : ''}`
        : `Rejects at sorting are ${vsRef}; no defect category is rising against the 24 h before — the most frequent in the last hour is ${label.toLowerCase()}, which usually originates at ${STAGE_BY_ID[origin].name.toLowerCase()}.${scenario ? ' (Scenario input active.)' : ''}`,
      evidence: [
        `Since ${formatClock(from)}: ${Math.round(recent.rejected)} of ${Math.round(recent.inspected)} inspected tiles rejected.`,
        top
          ? `${top.label}: ${pct(top.recentRate ?? 0, 2)} of tiles in the last 2 h vs ${pct(top.referenceRate ?? 0, 2)} in the 24 h before (deterioration rule, ≥ ${rise.threshold.ratio}×).`
          : `No category reaches the deterioration rule (≥ ${rise.threshold.ratio}× its 24 h rate over the last 2 h).`,
        `Affected batch: ${batch.id} (tiles fired ≈ 3 h after pressing).`,
      ],
      impact: `≈ ${m2((recent.rejected - recent.inspected * rref) / hrs)} m²/h of extra rejects`,
      recommendation: DEFECT_ACTIONS[d],
      equipmentId: STAGE_BY_ID[origin].machines[0],
      links: [
        { kind: 'equipment', id: 'I-VIS', label: 'Locate inspection tunnel' },
        { kind: 'equipment', id: STAGE_BY_ID[origin].machines[0], label: `Origin: ${STAGE_BY_ID[origin].name}` },
        { kind: 'workspace', id: 'quality', label: 'Open Quality & Defects' },
      ],
      weight: RANK[rr > 0.05 ? 'serious' : 'warning'] + rr * 1000,
    },
  ];
}

export function healthAssessments(s: SimState): HealthAssessment[] {
  return HEALTH_ASSETS.map((a) => assess(s, a.id));
}

function healthRule(s: SimState): Insight[] {
  return healthAssessments(s)
    .filter((h) => h.level === 'watch' || h.level === 'warning' || h.level === 'alarm')
    .map((h) => {
      const sev: InsightSeverity = h.level === 'alarm' ? 'critical' : h.level === 'warning' ? 'serious' : 'warning';
      const comp = HEALTH_ASSETS.find((a) => a.id === h.id)!.component;
      return {
        id: `health-${h.id}`,
        kind: 'health' as const,
        severity: sev,
        title: `${h.id} ${h.level === 'watch' ? 'health watch' : h.level === 'warning' ? 'abnormal trend' : 'alarm limit reached'} · ${comp.split(' · ')[1] ?? comp}`,
        summary: `${name(h.id)}: health score ${h.score}/100${h.etaTripH != null ? `; trip limit in ≈ ${formatH(h.etaTripH)} if the trend continues` : ''}.`,
        evidence: h.findings.length ? h.findings : ['Signals within limits but trending.'],
        impact: h.impact ?? undefined,
        recommendation: h.recommendation ?? undefined,
        equipmentId: h.id,
        links: [
          { kind: 'equipment' as const, id: h.id, label: `Open ${h.id} in the Factory Twin` },
        ],
        weight: RANK[sev] + (100 - h.score),
      };
    });
}

function logisticsRule(s: SimState): Insight[] {
  const out: Insight[] = [];
  const fm = fleetMetrics(s, resolvePeriod('shift', s.minute));
  if (fm.waiting >= 3)
    out.push({
      id: 'yard',
      kind: 'logistics',
      severity: fm.waiting >= 5 ? 'serious' : 'warning',
      title: `${fm.waiting} trucks waiting for a dock`,
      summary: `All docks are occupied or reserved; ${fm.waiting} outbound trucks are queuing in the holding area.`,
      evidence: [`Dock utilisation this shift ${pct(fm.dockUtilisation, 0)}; average gate→dock ${fm.avgGateToDock != null ? `${Math.round(fm.avgGateToDock)} min` : '—'}.`],
      recommendation: 'Release docks faster (pre-stage pallets, add a loading forklift) or re-sequence arrivals with carriers.',
      links: [
        { kind: 'equipment', id: 'A-HOLD', label: 'Locate holding area' },
        { kind: 'workspace', id: 'fleet', label: 'Open Fleet & Movement' },
      ],
      weight: RANK[fm.waiting >= 5 ? 'serious' : 'warning'] + fm.waiting,
    });
  for (const [dockId, d] of Object.entries(s.logistics.docks)) {
    if (!d.vehicleId || d.since == null || s.minute - d.since < 75) continue;
    const v = s.logistics.vehicles[d.vehicleId];
    out.push({
      id: `dock-${dockId}`,
      kind: 'logistics',
      severity: 'warning',
      title: `${v.label} at dock for ${formatDuration(s.minute - d.since)}`,
      summary: 'Prolonged dock stay blocks the dock for the next truck.',
      evidence: [`Docked since ${formatClock(d.since)}.`],
      recommendation: 'Check paperwork / loading status with the dock supervisor and release the dock.',
      links: [
        { kind: 'vehicle', id: v.id, label: `Follow ${v.label}` },
        { kind: 'workspace', id: 'fleet', label: 'Open Fleet & Movement' },
      ],
      weight: RANK.warning + (s.minute - d.since) / 10,
    });
  }
  return out;
}

function shiftRule(s: SimState): Insight[] {
  const prev = lineMetrics(s, resolvePeriod('prev-shift', s.minute));
  const cur = lineMetrics(s, resolvePeriod('shift', s.minute));
  if (prev.oee.oee.status !== 'ok' || cur.oee.oee.status !== 'ok' || cur.period.to - cur.period.from < 60) return [];
  const d = (cur.oee.oee.value! - prev.oee.oee.value!) * 100;
  if (Math.abs(d) < 2) return [];
  return [
    {
      id: 'shift-compare',
      kind: 'shift',
      severity: d > 0 ? 'positive' : 'info',
      title: `OEE ${d > 0 ? 'up' : 'down'} ${Math.abs(d).toFixed(1)} pts vs previous shift`,
      summary: `Current shift ${pct(cur.oee.oee.value!)} vs ${pct(prev.oee.oee.value!)} in ${prev.period.label}.`,
      evidence: [`Previous shift output ${m2(prev.output)} m² (${prev.attainment != null ? pct(prev.attainment, 0) : '—'} of target).`],
      links: [{ kind: 'workspace', id: 'production', label: 'Shift performance' }],
      weight: RANK[d > 0 ? 'positive' : 'info'],
    },
  ];
}

/** All current insights, most important first. */
export function insights(s: SimState, opts: { period?: Period; tariffs?: Tariffs } = {}): Insight[] {
  const p = opts.period ?? resolvePeriod('shift', s.minute);
  return [
    ...stoppageRule(s),
    ...healthRule(s),
    ...qualityRule(s),
    ...bufferRule(s),
    ...bottleneckRule(s),
    ...targetRule(s, p),
    ...logisticsRule(s),
    ...shiftRule(s),
  ].sort((a, b) => b.weight - a.weight);
}

/** Recommendations relevant to one asset (inspector "AI recommendations"). */
export function recommendationsFor(s: SimState, equipmentId: string, opts: { tariffs?: Tariffs } = {}): Insight[] {
  const stage = OPS_BY_ID[equipmentId]?.stage;
  return insights(s, opts).filter(
    (i) =>
      i.equipmentId === equipmentId ||
      i.links.some((l) => l.kind === 'equipment' && l.id === equipmentId) ||
      (stage && i.kind === 'bottleneck' && STAGE_BY_ID[stage].machines.includes(i.equipmentId ?? '')),
  );
}

/** Prioritised next actions (insights that carry a recommendation). */
export function nextActions(s: SimState, opts: { tariffs?: Tariffs } = {}) {
  return insights(s, opts)
    .filter((i) => i.recommendation && i.severity !== 'positive')
    .slice(0, 6);
}
